// Exact O58 K28 compression with (kp,kc)=(13,15), overlap3.
// Input support CSV is exhaustively generated by o58_k28_overlap3_supports.py.
// For each support, choose all p signs summing1, the three c signs at the
// overlap with their product sum +1, solve remaining c signs by GF3 RREF,
// and check the full original integer periodic cross equation and spectrum.
#include <bits/stdc++.h>
#include <omp.h>
using namespace std;
using A=array<int,25>;
using U=uint32_t;
int md(int x){x%=3;return x<0?x+3:x;}
struct Sol{int rank=0,piv[12]{},rhs[13]{},M[13][12]{};bool good=true;vector<int>fr;};
Sol rref(A const&p,vector<int>const&unknown,A const&fixed){
 Sol z;assert(unknown.size()==12);
 for(int j=0;j<12;j++){
  int i=unknown[j];
  for(int r=1;r<=12;r++)z.M[r-1][j]=md(p[(i-r+25)%25]+p[(i+r)%25]);
  z.M[12][j]=1;
 }
 int fixedsum=0;for(int j=0;j<25;j++)fixedsum+=fixed[j];
 for(int r=1;r<=12;r++){
  int val=0;
  for(int j=0;j<25;j++)if(fixed[j])val+=fixed[j]*(p[(j-r+25)%25]+p[(j+r)%25]);
  z.rhs[r-1]=md(-val);
 }
 z.rhs[12]=md(1-fixedsum);
 for(int c=0;c<12;c++){
  int q=-1;for(int r=z.rank;r<13;r++)if(z.M[r][c]){q=r;break;}
  if(q<0)continue;swap(z.M[q],z.M[z.rank]);swap(z.rhs[q],z.rhs[z.rank]);
  if(z.M[z.rank][c]==2){
   for(int j=0;j<12;j++)z.M[z.rank][j]=md(2*z.M[z.rank][j]);
   z.rhs[z.rank]=md(2*z.rhs[z.rank]);
  }
  for(int r=0;r<13;r++)if(r!=z.rank&&z.M[r][c]){
   int f=z.M[r][c];
   for(int j=0;j<12;j++)z.M[r][j]=md(z.M[r][j]-f*z.M[z.rank][j]);
   z.rhs[r]=md(z.rhs[r]-f*z.rhs[z.rank]);
  }
  z.piv[z.rank++]=c;
 }
 for(int r=z.rank;r<13;r++)if(z.rhs[r])z.good=false;
 bool is[12]{};for(int r=0;r<z.rank;r++)is[z.piv[r]]=1;
 for(int j=0;j<12;j++)if(!is[j])z.fr.push_back(j);
 return z;
}
int H(A const&p,A const&c,int r){int x=0;for(int i=0;i<25;i++)x+=p[i]*c[(i+r)%25]+c[i]*p[(i+r)%25];return x;}
int G(A const&p,A const&c,int r){int x=0;for(int i=0;i<25;i++)x+=p[i]*p[(i+r)%25]+c[i]*c[(i+r)%25];return x;}
int qmin(A const&p,A const&c,int&sg){
 int q=0;sg=0;for(int r=1;r<=12;r++){int g=G(p,c,r);sg+=g*g;q+=(g*g+(abs(g)&1))/2;}return q;
}
void print(A const&p){for(int i=0;i<25;i++){if(i)cout<<',';cout<<p[i];}}
int main(int argc,char**argv){
 if(argc<2)return 2;
 ifstream f(argv[1]);vector<pair<U,U>>supp;string line;
 while(getline(f,line)){
  auto i=line.find(',');supp.emplace_back(stoul(line.substr(0,i)),stoul(line.substr(i+1)));
 }
 assert(supp.size()==2194);
 atomic<long long>ptests{0},systems{0},exact{0},spectral{0};
 atomic<int>minSG{INT_MAX},minQ{INT_MAX},maxfree{0};
 #pragma omp parallel for schedule(dynamic,1)
 for(int si=0;si<(int)supp.size();si++){
  U T=supp[si].first,P=supp[si].second,C=(((1u<<25)-1)^P)|T;
  assert(__builtin_popcount(T)==3&&__builtin_popcount(P)==13&&__builtin_popcount(C)==15&&(P&C)==T);
  vector<int>pp,other,shared;
  for(int i=0;i<25;i++){
   if(P>>i&1)pp.push_back(i);
   if((C>>i&1)&&!(T>>i&1))other.push_back(i);
   if(T>>i&1)shared.push_back(i);
  }
  assert(other.size()==12&&shared.size()==3);
  for(int sign=0;sign<(1<<13);sign++)if(__builtin_popcount((unsigned)sign)==6){
   A p{};for(int j=0;j<13;j++)p[pp[j]]=(sign>>j&1)?-1:1;
   for(int flip=0;flip<3;flip++){
    ptests++;A fixed{};
    for(int j=0;j<3;j++)fixed[shared[j]]=p[shared[j]]*(j==flip?-1:1);
    auto z=rref(p,other,fixed);if(!z.good)continue;systems++;
    int old=maxfree.load();while(int(z.fr.size())>old&&!maxfree.compare_exchange_weak(old,int(z.fr.size()))){}
    long long lim=1;for(int v:z.fr)lim*=3;
    int fs=0;for(int v:fixed)fs+=v;
    assert((12+1-fs)%2==0);int wantPlus=(12+1-fs)/2;
    for(long long t=0;t<lim;t++){
     int x[12]{};auto w=t;
     for(int v:z.fr){x[v]=w%3;w/=3;}
     for(int r=z.rank-1;r>=0;r--){
      int y=z.rhs[r];for(int v:z.fr)y-=z.M[r][v]*x[v];
      x[z.piv[r]]=md(y);
     }
     int plus=0;bool ok=true;
     for(int j=0;j<12;j++){if(!x[j]){ok=false;break;}plus+=x[j]==1;}
     if(!ok||plus!=wantPlus)continue;
     A c=fixed;for(int j=0;j<12;j++)c[other[j]]=x[j]==1?1:-1;
     for(int r=0;r<=12;r++)if(H(p,c,r)!=(r==0?2:0)){ok=false;break;}
     if(!ok)continue;exact++;
     int sg,q=qmin(p,c,sg);
     int old=minSG.load();while(sg<old&&!minSG.compare_exchange_weak(old,sg)){}
     old=minQ.load();while(q<old&&!minQ.compare_exchange_weak(old,q)){}
     if(q<=60){spectral++;
      #pragma omp critical
      {cout<<"HIT SG="<<sg<<" qmin="<<q<<" p=";print(p);cout<<"|c=";print(c);cout<<'\n';}
     }
    }
   }
  }
 }
 cout<<"SUMMARY supports="<<supp.size()<<" ptests="<<ptests
     <<" modular_systems="<<systems<<" exact="<<exact
     <<" minSG="<<minSG<<" minQ="<<minQ<<" qmin60="<<spectral
     <<" maxfree="<<maxfree<<'\n';
}
